            return root;
        TreeNode* lt=lowestCommonAncestor(root->left,p,q);
        TreeNode* rt=lowestCommonAncestor(root->right,p,q);
        if(lt==NULL)
            return rt;
        else if(rt==NULL)
            return lt;
        else
